import{z as n,x as o,o as A,c as d,q as l,j as t,D as a,d as e,s,S as r,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"查询优化案例与收束","description":"","frontmatter":{"title":"查询优化案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-case-map.md","filePath":"cs/qo-case-map.md","lastUpdated":1791413859000}'),p={name:"cs/qo-case-map.md"};function C(F,E,D,c,h,u){const i=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="查询优化案例与收束" tabindex="-1">查询优化案例与收束 <a class="header-anchor" href="#查询优化案例与收束" aria-label="Permalink to &quot;查询优化案例与收束&quot;">​</a></h1><div class="epigraph"><p>诊断慢查询的顺序不该由直觉决定：先核对数字，再核对尺子，再核对空间，最后才轮到「换个写法」。</p><footer>—— 据 Chaudhuri, An Overview of Query Optimization, 1998；Graefe 查询执行综述；本课程口径整理</footer></div><p><a href="/cs/qo-materialized-views">上一课</a>把优化外置到存储。本课收束：用两个案例把代价模型、join 实现、统计、空间、自适应、向量化、物化串成一条诊断链，再给出课程地图。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个高频事故，症状都是「忽然慢」。案例一：同一句 SQL 昨天八十毫秒今天八秒。案例二：大表连接把内存打爆，磁盘读抖动。缺口不是「优化器有 bug」，而是诊断没有顺序：直觉先去改写 SQL，把病因留在原地，换个参数再犯一次。诊断链的每一环都对应本课程的一课，每一环都要有可验证的判据——「感觉优化器傻」不是判据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例一的链条。第一步 explain analyze：逐节点对比估计行数与实际行数，比值超一个数量级记为可疑——数字先于一切。第二步查统计：批量变更后是否没触发收集，相关列是否缺<a href="/cs/qo-statistics">列组统计</a>，函数依赖是否声明。第三步查尺子：执行引擎或参数是否变过、代价权重是否失配——固定真实基数、只改权重的对照实验能把「统计错」与「权重错」分开，这是校准课的手法。第四步查缓存：参数窥视是否把坏计划锁死，通用与定制的竞赛是否选错边。修复按侵入度递增：刷统计、补统计、加<a href="/cs/plan-hints-stability">提示</a>或计划基线。案例二的链条。先看执行器：build 侧是否选错（低估所致）、是否已转分区溢出、溢出分区数多少。短期用提示指定 build 侧或加内存预算止血；中期修统计让估计回轨；长期靠<a href="/cs/qo-adaptive-execution">自适应执行</a>的止损——运行时过滤器把 probe 侧提前瘦身，算子内切换让溢出方式自适应。每层修复都回到判据：估计/实际比、布隆过滤率、溢出分区数，由数字说话。</p>',7)),(A(),t(r,null,{default:a(()=>[s(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLOW%5B%22%E6%85%A2%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20EA%5B%22explain%20analyze%22%5D%0A%20%20EA%20--%3E%20RAT%7B%22%E4%BC%B0%E8%AE%A1%2F%E5%AE%9E%E9%99%85%E6%AF%94%E8%B6%85%E4%B8%80%E4%B8%AA%E9%87%8F%E7%BA%A7%EF%BC%9F%22%7D%0A%20%20RAT%20--%3E%7C%E6%98%AF%7C%20STAT%5B%22%E4%BF%AE%E7%BB%9F%E8%AE%A1%EF%BC%9A%E6%94%B6%E9%9B%86%20%2F%20%E5%88%97%E7%BB%84%20%2F%20%E4%BE%9D%E8%B5%96%22%5D%0A%20%20RAT%20--%3E%7C%E5%90%A6%7C%20W%5B%22%E6%A0%B8%E4%BB%A3%E4%BB%B7%E6%9D%83%E9%87%8D%E4%B8%8E%E6%89%A7%E8%A1%8C%E5%BC%95%E6%93%8E%22%5D%0A%20%20STAT%20--%3E%20CACHE%5B%22%E6%9F%A5%E8%AE%A1%E5%88%92%E7%BC%93%E5%AD%98%E4%B8%8E%E5%8F%82%E6%95%B0%E7%AA%A5%E8%A7%86%22%5D%0A%20%20W%20--%3E%20CACHE%0A%20%20CACHE%20--%3E%20FIX%5B%22%E6%8F%90%E7%A4%BA%20%2F%20%E5%9F%BA%E7%BA%BF%20%2F%20%E8%87%AA%E9%80%82%E5%BA%94%E6%AD%A2%E6%8D%9F%22%5D%0A%20%20FIX%20--%3E%20RE%5B%22%E5%9B%9E%E5%88%B0%E5%88%A4%E6%8D%AE%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"两个案例共享同一结构：优化器是估计驱动的搜索，任何一环失真都表现为计划变坏，所以诊断必须沿数据流逆行——从执行（实现常数）退到计划（空间与代价），再退到输入（统计）。跳环诊断——不比估计直接改写 SQL——多数时候是在给症状化妆。案例的死因要落在判据上，这是整门课程的方法论：每一课都留了测量点——代价模型给询价接口，join 实现给缓存与溢出计数，统计给摘要刷新记录，空间给枚举预算与超时行为，自适应给监测阈值，向量化给宽度与压缩域执行，物化视图给匹配率与刷新代价。慢的病因几乎总落在其中一格。",-1)),(A(),t(r,null,{default:a(()=>[s(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPILL%5B%22%E6%A1%88%E4%BE%8B%E4%BA%8C%EF%BC%9A%E5%A4%A7%E8%A1%A8%E8%BF%9E%E6%8E%A5%E5%86%85%E5%AD%98%E6%89%93%E7%88%86%22%5D%20--%3E%20EX%7B%22%E6%89%A7%E8%A1%8C%E5%99%A8%EF%BC%9Abuild%20%E4%BE%A7%E9%80%89%E5%AF%B9%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20EX%20--%3E%7C%22%E9%80%89%E9%94%99%E4%B8%94%E5%9B%A0%E4%BD%8E%E4%BC%B0%22%7C%20STOP%5B%22%E7%9F%AD%E6%9C%9F%E6%AD%A2%E8%A1%80%EF%BC%9A%E6%8F%90%E7%A4%BA%E6%8C%87%E5%AE%9A%20build%20%E4%BE%A7%E6%88%96%E5%8A%A0%E5%86%85%E5%AD%98%E9%A2%84%E7%AE%97%22%5D%0A%20%20EX%20--%3E%7C%22%E5%B7%B2%E6%BA%A2%E5%87%BA%22%7C%20P%5B%22%E7%9C%8B%E6%BA%A2%E5%87%BA%E5%88%86%E5%8C%BA%E6%95%B0%E4%B8%8E%E7%A3%81%E7%9B%98%E8%AF%BB%E6%8A%96%E5%8A%A8%22%5D%0A%20%20STOP%20--%3E%20STAT%5B%22%E4%B8%AD%E6%9C%9F%E4%BF%AE%E7%BB%9F%E8%AE%A1%E8%AE%A9%E4%BC%B0%E8%AE%A1%E5%9B%9E%E8%BD%A8%22%5D%0A%20%20P%20--%3E%20STAT%0A%20%20STAT%20--%3E%20AD%5B%22%E9%95%BF%E6%9C%9F%E8%87%AA%E9%80%82%E5%BA%94%E6%AD%A2%E6%8D%9F%EF%BC%9A%E8%BF%87%E6%BB%A4%E5%99%A8%E4%B8%8B%E6%8E%A8%E4%B8%8E%E7%AE%97%E5%AD%90%E5%86%85%E5%88%87%E6%8D%A2%22%5D%0A%20%20AD%20--%3E%20V%5B%22%E5%9B%9E%E5%88%A4%E6%8D%AE%EF%BC%9A%E4%BC%B0%E8%AE%A1%2F%E5%AE%9E%E9%99%85%E6%AF%94%E3%80%81%E8%BF%87%E6%BB%A4%E7%8E%87%E3%80%81%E5%88%86%E5%8C%BA%E6%95%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">归档口径：每个案例四行——症状、判据、修复、验证。死因写「统计过期低估三百倍，build 侧选错致溢出」，不写「优化器抽风」；判据可检索，下次排查从数字开始。</span></p><p><span class="marginnote">explain analyze 就是「真跑一遍并记账」：普通 explain 只给你优化器的估计，analyze 会实际执行，把每个节点真实处理了多少行记下来。术语翻译：它是「计划 + 实测」的对照表，第一环先看它，就是在问「尺子和现实差多远」。</span></p><p><span class="marginnote">数字实例：「低估三百倍」代入一下——统计说 build 侧只有 1 千行，优化器放心选它做哈希表；实际跑出 30 万行，表膨胀三百倍，内存装不下，只好溢写磁盘，磁盘读抖动就是这么来的。</span></p><p><span class="marginnote">常见误区：直觉一慢就去改写 SQL，等于发烧不量体温直接吃药——症状可能压下去，病因留在原地，换个参数再犯一次。正确顺序是沿数据流逆行：先看执行读数，再对尺子（代价权重），最后查输入（统计）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不覆盖跨节点的诊断（shuffle、时钟与副本），也不覆盖锁等待与缓冲池的病因——那分别是分布式事务与存储进阶的领地，主干已立。学习型优化器与自动物理设计顾问是两条已在主干点名的延伸线。本课程到此收束，把「模型、输入、空间、止损、执行、外置」六个词留在地图上：读数、对尺、搜空间、加止损、摊批、外置存储，就是查询优化的全部日常。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诊断沿数据流逆行：先估计/实际比，再统计，再尺子，最后才是改写。</li><li>每层修复配一个判据；没有判据的修复是化妆。</li><li>八课一线：询价、实现常数、摘要输入、空间搜索、执行止损、批摊销、存储外置。</li><li>案例同模板归档，死因落在判据，下次可检索。</li><li>出处：Chaudhuri, 1998；Graefe 综述；本课程各课口径。</li></ul>',8))])}const T=n(p,[["render",C]]);export{f as __pageData,T as default};
